"""Host-only ground truth + metric for cv-model-merge-rule (A-pattern).

The container never sees labels: the merge harness prints per-image argmax
predictions keyed by opaque task id (`PREDICTIONS <opaque_id> <n> <base64 int16>`),
and `parser.py` calls into this module -- which lives on the host (dev) or inside
the Harbor bundle's `tests/meta/` (never the workspace) -- to score them.

Labels are committed .npy vectors under `labels/<setting>/<opaque_id>.npy`, in the
same dataset index order the images were baked in (see gen_labels.py /
prepare_data.py).  Nothing here imports torch."""
import json
import os
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent


def _labels_root() -> Path:
    return _HERE / "labels"


def opaque_labels(setting: str):
    """List of opaque task ids for a setting, from the committed manifest."""
    man = _HERE / f"manifest_{setting}.json"
    with open(man) as f:
        return list(json.load(f)["task_labels"])


def truth(setting: str, opaque_id: str) -> np.ndarray:
    """Ground-truth integer labels for one opaque task, in baked image order."""
    p = _labels_root() / setting / f"{opaque_id}.npy"
    if not p.exists():
        raise FileNotFoundError(f"held-out labels not found host-side: {p}")
    return np.load(p)


def accuracy(preds: np.ndarray, labels: np.ndarray) -> float:
    """Top-1 accuracy (%) with strict length check."""
    preds = np.asarray(preds).reshape(-1)
    labels = np.asarray(labels).reshape(-1)
    if preds.shape[0] != labels.shape[0]:
        raise ValueError(
            f"prediction count {preds.shape[0]} != label count {labels.shape[0]}")
    if preds.shape[0] == 0:
        raise ValueError("empty prediction/label vector")
    return 100.0 * float((preds == labels).mean())


def score_task(setting: str, opaque_id: str, preds: np.ndarray) -> float:
    """Accuracy of `preds` for one opaque task against the held-out labels."""
    return accuracy(preds, truth(setting, opaque_id))
